232	static void
233	usage(void)
234	{
235	    printf(
236	        "Usage: md2html [OPTION]... [FILE]\n"
237	        "Convert input FILE (or standard input) in Markdown format to HTML.\n"
238	        "\n"
239	        "General options:\n"
240	        "  -o  --output=FILE    Output file (default is standard output)\n"
241	        "  -f, --full-html      Generate full HTML document, including header\n"
242	        "  -x, --xhtml          Generate XHTML instead of HTML\n"
243	        "  -s, --stat           Measure time of input parsing\n"
244	        "  -h, --help           Display this help and exit\n"
245	        "  -v, --version        Display version and exit\n"
246	        "\n"
247	        "Markdown dialect options:\n"
248	        "(note these are equivalent to some combinations of the flags below)\n"
249	        "      --commonmark     CommonMark (this is default)\n"
250	        "      --github         Github Flavored Markdown\n"
251	        "\n"
252	        "Markdown extension options:\n"
253	        "      --fcollapse-whitespace\n"
254	        "                       Collapse non-trivial whitespace\n"
255	        "      --flatex-math    Enable LaTeX style mathematics spans\n"
256	        "      --fpermissive-atx-headers\n"
257	        "                       Allow ATX headers without delimiting space\n"
258	        "      --fpermissive-url-autolinks\n"
259	        "                       Allow URL autolinks without '<', '>'\n"
260	        "      --fpermissive-www-autolinks\n"
261	        "                       Allow WWW autolinks without any scheme (e.g. 'www.example.com')\n"
262	        "      --fpermissive-email-autolinks  \n"
263	        "                       Allow e-mail autolinks without '<', '>' and 'mailto:'\n"
264	        "      --fpermissive-autolinks\n"
