35	
36	/* Global options. */
37	static unsigned parser_flags = 0;
38	#ifndef MD4C_USE_ASCII
39	    static unsigned renderer_flags = MD_HTML_FLAG_DEBUG | MD_HTML_FLAG_SKIP_UTF8_BOM;
40	#else
41	    static unsigned renderer_flags = MD_HTML_FLAG_DEBUG;
42	#endif
43	static int want_fullhtml = 0;
44	static int want_xhtml = 0;
45	static int want_stat = 0;
46	
47	
48	/*********************************
49	 ***  Simple grow-able buffer  ***
50	 *********************************/
51	
52	/* We render to a memory buffer instead of directly outputting the rendered
53	 * documents, as this allows using this utility for evaluating performance
54	 * of MD4C (--stat option). This allows us to measure just time of the parser,
55	 * without the I/O.
56	 */
57	
58	struct membuffer {
59	    char* data;
60	    size_t asize;
61	    size_t size;
62	};
63	
64	static void
65	membuf_init(struct membuffer* buf, MD_SIZE new_asize)
66	{
67	    buf->size = 0;
68	    buf->asize = new_asize;
69	    buf->data = malloc(buf->asize);
70	    if(buf->data == NULL) {
71	        fprintf(stderr, "membuf_init: malloc() failed.\n");
72	        exit(1);
73	    }
74	}
75	
76	static void
77	membuf_fini(struct membuffer* buf)
78	{
79	    if(buf->data)
80	        free(buf->data);
81	}
82	
83	static void
84	membuf_grow(struct membuffer* buf, size_t new_asize)
85	{
86	    buf->data = realloc(buf->data, new_asize);
87	    if(buf->data == NULL) {
88	        fprintf(stderr, "membuf_grow: realloc() failed.\n");
89	        exit(1);
90	    }
91	    buf->asize = new_asize;
92	}
93	
94	static void
95	membuf_append(struct membuffer* buf, const char* data, MD_SIZE size)
96	{
97	    if(buf->asize < buf->size + size)
98	        membuf_grow(buf, buf->size + buf->size / 2 + size);
99	    memcpy(buf->data + buf->size, data, size);
100	    buf->size += size;
101	}
102	
103	
104	/**********************
105	 ***  Main program  ***
106	 **********************/
107	
108	static void
109	process_output(const MD_CHAR* text, MD_SIZE size, void* userdata)
110	{
111	    membuf_append((struct membuffer*) userdata, text, size);
112	}
113	
114	static int
115	process_file(FILE* in, FILE* out)
116	{
117	    size_t n;
118	    struct membuffer buf_in = {0};
119	    struct membuffer buf_out = {0};
120	    int ret = -1;
121	    clock_t t0, t1;
122	
123	    membuf_init(&buf_in, 32 * 1024);
124	
125	    /* Read the input file into a buffer. */
126	    while(1) {
127	        if(buf_in.size >= buf_in.asize)
128	            membuf_grow(&buf_in, buf_in.asize + buf_in.asize / 2);
129	
130	        n = fread(buf_in.data + buf_in.size, 1, buf_in.asize - buf_in.size, in);
131	        if(n == 0)
132	            break;
133	        buf_in.size += n;
134	    }
135	
136	    /* Input size is good estimation of output size. Add some more reserve to
137	     * deal with the HTML header/footer and tags. */
138	    membuf_init(&buf_out, (MD_SIZE)(buf_in.size + buf_in.size/8 + 64));
139	
140	    /* Parse the document. This shall call our callbacks provided via the
141	     * md_renderer_t structure. */
142	    t0 = clock();
143	
144	    ret = md_html(buf_in.data, (MD_SIZE)buf_in.size, process_output, (void*) &buf_out,
145	                    parser_flags, renderer_flags);
146	
147	    t1 = clock();
148	    if(ret != 0) {
149	        fprintf(stderr, "Parsing failed.\n");
150	        goto out;
151	    }
152	
153	    /* Write down the document in the HTML format. */
154	    if(want_fullhtml) {
155	        if(want_xhtml) {
156	            fprintf(out, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
157	            fprintf(out, "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" "
158	                            "\"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n");
159	            fprintf(out, "<html xmlns=\"http://www.w3.org/1999/xhtml\">\n");
160	        } else {
161	            fprintf(out, "<!DOCTYPE html>\n");
162	            fprintf(out, "<html>\n");
163	        }
164	        fprintf(out, "<head>\n");
165	        fprintf(out, "<title></title>\n");
166	        fprintf(out, "<meta name=\"generator\" content=\"md2html\"%s>\n", want_xhtml ? " /" : "");
167	        fprintf(out, "</head>\n");
168	        fprintf(out, "<body>\n");
169	    }
170	
171	    fwrite(buf_out.data, 1, buf_out.size, out);
172	
173	    if(want_fullhtml) {
174	        fprintf(out, "</body>\n");
175	        fprintf(out, "</html>\n");
176	    }
177	
178	    if(want_stat) {
179	        if(t0 != (clock_t)-1  &&  t1 != (clock_t)-1) {
180	            double elapsed = (double)(t1 - t0) / CLOCKS_PER_SEC;
181	            if (elapsed < 1)
182	                fprintf(stderr, "Time spent on parsing: %7.2f ms.\n", elapsed*1e3);
183	            else
184	                fprintf(stderr, "Time spent on parsing: %6.3f s.\n", elapsed);
185	        }
186	    }
187	
188	    /* Success if we have reached here. */
189	    ret = 0;
190	
191	out:
192	    membuf_fini(&buf_in);
193	    membuf_fini(&buf_out);
194	
195	    return ret;
196	}
