232	static void
233	usage(void)
234	{
235	    printf(
236	        "Usage: md2html [OPTION]... [FILE]\n"
237	        "Convert input FILE (or standard input) in Markdown format to HTML.\n"
238	        "\n"
239	        "General options:\n"
240	        "  -o  --output=FILE    Output file (default is standard output)\n"
241	        "  -f, --full-html      Generate full HTML document, including header\n"
242	        "  -x, --xhtml          Generate XHTML instead of HTML\n"
243	        "  -s, --stat           Measure time of input parsing\n"
244	        "  -h, --help           Display this help and exit\n"
245	        "  -v, --version        Display version and exit\n"
246	        "\n"
247	        "Markdown dialect options:\n"
248	        "(note these are equivalent to some combinations of the flags below)\n"
249	        "      --commonmark     CommonMark (this is default)\n"
250	        "      --github         Github Flavored Markdown\n"
251	        "\n"
252	        "Markdown extension options:\n"
253	        "      --fcollapse-whitespace\n"
254	        "                       Collapse non-trivial whitespace\n"
255	        "      --flatex-math    Enable LaTeX style mathematics spans\n"
256	        "      --fpermissive-atx-headers\n"
257	        "                       Allow ATX headers without delimiting space\n"
258	        "      --fpermissive-url-autolinks\n"
259	        "                       Allow URL autolinks without '<', '>'\n"
260	        "      --fpermissive-www-autolinks\n"
261	        "                       Allow WWW autolinks without any scheme (e.g. 'www.example.com')\n"
262	        "      --fpermissive-email-autolinks  \n"
263	        "                       Allow e-mail autolinks without '<', '>' and 'mailto:'\n"
264	        "      --fpermissive-autolinks\n"
265	        "                       Same as --fpermissive-url-autolinks --fpermissive-www-autolinks\n"
266	        "                       --fpermissive-email-autolinks\n"
267	        "      --fstrikethrough Enable strike-through spans\n"
268	        "      --ftables        Enable tables\n"
269	        "      --ftasklists     Enable task lists\n"
270	        "      --funderline     Enable underline spans\n"
271	        "      --fwiki-links    Enable wiki links\n"
272	        "\n"
273	        "Markdown suppression options:\n"
274	        "      --fno-html-blocks\n"
275	        "                       Disable raw HTML blocks\n"
276	        "      --fno-html-spans\n"
277	        "                       Disable raw HTML spans\n"
278	        "      --fno-html       Same as --fno-html-blocks --fno-html-spans\n"
279	        "      --fno-indented-code\n"
280	        "                       Disable indented code blocks\n"
281	        "\n"
282	        "HTML generator options:\n"
283	        "      --fverbatim-entities\n"
284	        "                       Do not translate entities\n"
285	        "\n"
286	    );
287	}
288	
289	static void
290	version(void)
291	{
292	    printf("%d.%d.%d\n", MD_VERSION_MAJOR, MD_VERSION_MINOR, MD_VERSION_RELEASE);
293	}
294	
295	static const char* input_path = NULL;
296	static const char* output_path = NULL;
297	
298	static int
299	cmdline_callback(int opt, char const* value, void* data)
300	{
301	    switch(opt) {
302	        case 0:
303	            if(input_path) {
304	                fprintf(stderr, "Too many arguments. Only one input file can be specified.\n");
305	                fprintf(stderr, "Use --help for more info.\n");
306	                exit(1);
307	            }
308	            input_path = value;
309	            break;
310	
311	        case 'o':   output_path = value; break;
312	        case 'f':   want_fullhtml = 1; break;
313	        case 'x':   want_xhtml = 1; renderer_flags |= MD_HTML_FLAG_XHTML; break;
314	        case 's':   want_stat = 1; break;
315	        case 'h':   usage(); exit(0); break;
316	        case 'v':   version(); exit(0); break;
317	
318	        case 'c':   parser_flags = MD_DIALECT_COMMONMARK; break;
319	        case 'g':   parser_flags = MD_DIALECT_GITHUB; break;
320	
321	        case 'E':   renderer_flags |= MD_HTML_FLAG_VERBATIM_ENTITIES; break;
322	        case 'A':   parser_flags |= MD_FLAG_PERMISSIVEATXHEADERS; break;
323	        case 'I':   parser_flags |= MD_FLAG_NOINDENTEDCODEBLOCKS; break;
324	        case 'F':   parser_flags |= MD_FLAG_NOHTMLBLOCKS; break;
325	        case 'G':   parser_flags |= MD_FLAG_NOHTMLSPANS; break;
326	        case 'H':   parser_flags |= MD_FLAG_NOHTML; break;
327	        case 'W':   parser_flags |= MD_FLAG_COLLAPSEWHITESPACE; break;
328	        case 'U':   parser_flags |= MD_FLAG_PERMISSIVEURLAUTOLINKS; break;
329	        case '.':   parser_flags |= MD_FLAG_PERMISSIVEWWWAUTOLINKS; break;
330	        case '@':   parser_flags |= MD_FLAG_PERMISSIVEEMAILAUTOLINKS; break;
331	        case 'V':   parser_flags |= MD_FLAG_PERMISSIVEAUTOLINKS; break;
332	        case 'T':   parser_flags |= MD_FLAG_TABLES; break;
333	        case 'S':   parser_flags |= MD_FLAG_STRIKETHROUGH; break;
334	        case 'L':   parser_flags |= MD_FLAG_LATEXMATHSPANS; break;
335	        case 'K':   parser_flags |= MD_FLAG_WIKILINKS; break;
336	        case 'X':   parser_flags |= MD_FLAG_TASKLISTS; break;
337	        case '_':   parser_flags |= MD_FLAG_UNDERLINE; break;
338	
339	        default:
340	            fprintf(stderr, "Illegal option: %s\n", value);
341	            fprintf(stderr, "Use --help for more info.\n");
342	            exit(1);
343	            break;
344	    }
345	
346	    return 0;
347	}
348	
349	int
350	main(int argc, char** argv)
351	{
352	    FILE* in = stdin;
353	    FILE* out = stdout;
354	    int ret = 0;
355	
356	    if(cmdline_read(cmdline_options, argc, argv, cmdline_callback, NULL) != 0) {
357	        usage();
358	        exit(1);
359	    }
360	
361	    if(input_path != NULL && strcmp(input_path, "-") != 0) {
362	        in = fopen(input_path, "rb");
363	        if(in == NULL) {
364	            fprintf(stderr, "Cannot open %s.\n", input_path);
365	            exit(1);
366	        }
367	    }
368	    if(output_path != NULL && strcmp(output_path, "-") != 0) {
369	        out = fopen(output_path, "wt");
370	        if(out == NULL) {
371	            fprintf(stderr, "Cannot open %s.\n", output_path);
372	            exit(1);
373	        }
374	    }
375	
376	    ret = process_file(in, out);
377	    if(in != stdin)
378	        fclose(in);
379	    if(out != stdout)
380	        fclose(out);
381	
382	    return ret;
383	}
