50	typedef struct MD_HTML_tag MD_HTML;
51	struct MD_HTML_tag {
52	    void (*process_output)(const MD_CHAR*, MD_SIZE, void*);
53	    void* userdata;
54	    unsigned flags;
55	    int image_nesting_level;
56	    char escape_map[256];
57	};
