157	static unsigned
158	hex_val(char ch)
159	{
160	    if('0' <= ch && ch <= '9')
161	        return ch - '0';
162	    if('A' <= ch && ch <= 'Z')
163	        return ch - 'A' + 10;
164	    else
165	        return ch - 'a' + 10;
166	}
